        const PH_ICON_DEFAULT = '#c8cdd6';
        const PH_COLOR_AGUA = '#38bdf8';
        const PH_COLOR_SOL = '#fbbf24';
        const PH_COLOR_NOCHE = '#8b9cff';
        const PH_COLOR_ORO = '#e8c547';

        const HABIT_ICON_COLOR = {
            'hidratarse': PH_COLOR_AGUA,
            'nadar': PH_COLOR_AGUA,
            'bucear en arrecife': PH_COLOR_AGUA,
            'levantarse temprano': PH_COLOR_SOL,
            'no usar el movil al despertar': PH_COLOR_SOL,
            'acostarse temprano': PH_COLOR_NOCHE,
            'dormir 7/8h': PH_COLOR_NOCHE,
            'no usar el movil antes de dormir': PH_COLOR_NOCHE,
            'ahorrar': PH_COLOR_ORO,
            'subir la torre eiffel': '#d4a853'
        };

        const PH_ICON_COLOR = {
            drop: PH_COLOR_AGUA,
            'person-simple-swim': PH_COLOR_AGUA,
            waves: PH_COLOR_AGUA,
            sun: PH_COLOR_SOL,
            'sun-horizon': PH_COLOR_SOL,
            moon: PH_COLOR_NOCHE,
            'moon-stars': PH_COLOR_NOCHE,
            coins: PH_COLOR_ORO,
            'eiffel-tower': '#d4a853',
            flame: '#f97316',
            fire: '#f97316'
        };

        function colorIconoHabito(nombre) {
            const habitKey = claveIconoHabito(nombre);
            if (HABIT_ICON_COLOR[habitKey]) return HABIT_ICON_COLOR[habitKey];
            const iconKey = HABIT_ICON_BY_NAME[habitKey];
            return (iconKey && PH_ICON_COLOR[iconKey]) || PH_ICON_DEFAULT;
        }

        function claveIconoHabito(nombre) {
            return String(cleanHabitName(nombre) || '')
                .toLowerCase()
                .normalize('NFD')
                .replace(/[\u0300-\u036f]/g, '');
        }

        function nombreSugiereHabitoContinuo(nombre) {
            const clave = claveIconoHabito(nombre);
            return /hidratarse|beber agua|dejar de fumar|dejar de vappear|no fumar|pasar tiempo sin redes|pasar tiempo sin movil/.test(clave);
        }

        function extraerFechaUnica(momentos) {
            const m = (momentos || []).find(x => /^U:\d{4}-\d{2}-\d{2}$/.test(String(x)));
            return m ? String(m).slice(2) : '';
        }

        function extraerFechasUnicas(momentos) {
            const set = new Set();
            (momentos || []).forEach(x => {
                const m = String(x).match(/^U:(\d{4}-\d{2}-\d{2})$/);
                if (m) set.add(m[1]);
            });
            return Array.from(set).sort();
        }

        function fechasUnicasDeHabito(h) {
            if (!h) return [];
            let arr = [];
            if (Array.isArray(h.fechasUnicas) && h.fechasUnicas.length) arr = h.fechasUnicas.slice();
            if (!arr.length && h.fechaUnica) arr = [h.fechaUnica];
            if (!arr.length) arr = extraerFechasUnicas(h.momentos);
            return Array.from(new Set(arr.filter(Boolean))).sort();
        }

        function habitEsUnaVez(h) {
            if (!h) return false;
            if (h.unaVez) return true;
            if (String(h.tipo || '') === 'Una vez') return true;
            return !!extraerFechaUnica(h.momentos);
        }

        /** 'unaVez' | 'abstinencia' | 'ritual' */
        function naturalezaHabito(h) {
            if (!h) return 'ritual';
            if (habitEsUnaVez(h)) return 'unaVez';
            if (typeof habitEsAbstinencia === 'function' && habitEsAbstinencia(h)) return 'abstinencia';
            if (String(h.tipo || '').toLowerCase().indexOf('abstinen') !== -1) return 'abstinencia';
            return 'ritual';
        }

        function etiquetaNaturalezaHabito(h) {
            const n = naturalezaHabito(h);
            if (n === 'unaVez') return 'Actividad';
            if (n === 'abstinencia') return 'Abstinencia';
            return 'Hábito';
        }

        function copiaNaturalezaHabito(h) {
            const n = naturalezaHabito(h);
            if (n === 'unaVez') {
                return {
                    nombre: 'actividad',
                    nombrePlural: 'actividades',
                    articulo: 'la',
                    demostrativo: 'esta',
                    tituloEliminar: 'Eliminar actividad',
                    tituloEditar: 'Editar actividad',
                    tituloConfigurar: 'Configurar actividad',
                    sinRegistros: '¿Eliminar esta actividad? No tiene registros.',
                    conRegistros: 'Se borra la actividad y cualquier foto o nota. No se puede deshacer.',
                    toastEliminado: 'Actividad eliminada',
                    desellarTitulo: 'Quitar el sello',
                    desellarTexto: 'Se quita el registro de esta actividad, incluida la foto si la hay.',
                    metaCorta: 'Una vez'
                };
            }
            if (n === 'abstinencia') {
                return {
                    nombre: 'abstinencia',
                    nombrePlural: 'abstinencias',
                    articulo: 'la',
                    demostrativo: 'esta',
                    tituloEliminar: 'Eliminar abstinencia',
                    tituloEditar: 'Editar abstinencia',
                    tituloConfigurar: 'Configurar abstinencia',
                    sinRegistros: '¿Eliminar esta abstinencia? Aún no tiene registros.',
                    conRegistros: 'Se borra la abstinencia y su historial. No se puede deshacer.',
                    toastEliminado: 'Abstinencia eliminada',
                    desellarTitulo: 'Marcar recaída',
                    desellarTexto: 'El día dejará de estar sellado y la racha se rompe.',
                    metaCorta: 'Abstinencia'
                };
            }
            return {
                nombre: 'hábito',
                nombrePlural: 'hábitos',
                articulo: 'el',
                demostrativo: 'este',
                tituloEliminar: 'Eliminar hábito',
                tituloEditar: 'Editar hábito',
                tituloConfigurar: 'Configurar hábito',
                sinRegistros: '¿Eliminar este hábito? Aún no tiene sellos.',
                conRegistros: 'Se borra el hábito y su diario (fotos y notas). No se puede deshacer.',
                toastEliminado: 'Hábito eliminado',
                desellarTitulo: 'Quitar el sello',
                desellarTexto: 'Se elimina este registro del día, incluida cualquier foto.',
                metaCorta: 'Hábito'
            };
        }

        function fechaUnicaDeHabito(h) {
            return (h && h.fechaUnica) || extraerFechaUnica(h && h.momentos) || '';
        }

        function momentoDesdeHora(hhmm) {
            const n = parseInt(String(hhmm || '').split(':')[0], 10);
            if (isNaN(n)) return 'CUALQUIER';
            if (n < 12) return 'MAÑANA';
            if (n < 18) return 'TARDE';
            return 'NOCHE';
        }

        function momentosDeUnaVezList(fechasIso, hora) {
            const isos = Array.isArray(fechasIso) ? fechasIso.filter(Boolean) : String(fechasIso || '').split(',').filter(Boolean);
            const unicos = Array.from(new Set(isos)).sort();
            const lista = unicos.map(i => 'U:' + i);
            lista.push(momentoDesdeHora(hora));
            return lista;
        }

        function momentosDeUnaVez(fechaIso, hora) {
            return momentosDeUnaVezList([fechaIso], hora);
        }

        function aplicarModoContinuoHabito(h) {
            const nombre = cleanHabitName(h.nombre || '');
            const momentosIn = h.momentos || [];
            if (habitEsUnaVez(h)) {
                const fechasUnicas = fechasUnicasDeHabito(h);
                const fechaUnica = fechasUnicas[0] || fechaUnicaDeHabito(h);
                return { ...h, nombre, unaVez: true, fechasUnicas, fechaUnica, permite247: false };
            }
            const esContinuo = !!h.permite247 || momentosIn.indexOf('24/7') !== -1 || nombreSugiereHabitoContinuo(nombre);
            if (!esContinuo) {
                return { ...h, nombre, permite247: false };
            }
            return {
                ...h,
                nombre,
                momentos: ['24/7'],
                dias: [1, 2, 3, 4, 5, 6, 0],
                permite247: true
            };
        }

        function esHabitoContinuo(h, momento) {
            if (momento === '24/7') return true;
            if (!h) return false;
            if (h.permite247) return true;
            const momentos = h.momentos || [];
            if (momentos.indexOf('24/7') !== -1) return true;
            return nombreSugiereHabitoContinuo(h.nombre);
        }

        function habitoPermiteFoto(h, momento) {
            return !esHabitoContinuo(h, momento);
        }

        const AWAKE_MARK_OMITIDO = '[OMITIDO]';
