        function svgPhosphorPorClave(clave, size, color) {
            const s = size || 20;
            if (clave === 'pill') {
                return `<svg class="ph-icon" width="${s}" height="${s}" viewBox="0 0 256 256" aria-hidden="true"><path fill="#f8fafc" d="M205.11,103.6L160,148.69,107.32,96l45.1-45.09a37.26,37.26,0,0,1,52.69,52.69Z"/><path fill="#f87171" d="M103.61,205.09a37.26,37.26,0,0,1-52.7-52.69L96,107.31,148.7,160Z"/><g fill="${PH_ICON_DEFAULT}">${PH_ICON_PATHS.pill}</g></svg>`;
            }
            const inner = PH_ICON_PATHS[clave] || PH_ICON_PATHS.sparkle;
            const fill = color || PH_ICON_COLOR[clave] || PH_ICON_DEFAULT;
            return `<svg class="ph-icon" width="${s}" height="${s}" viewBox="0 0 256 256" fill="${fill}" aria-hidden="true">${inner}</svg>`;
        }

        function glyphElegidoUsuario(glyph) {
            const g = String(glyph || '').trim();
            if (g && PH_ICON_PATHS[g] && g !== 'sparkle') return g;
            return '';
        }

        function resolverGlyphAlGuardar(nombre, glyph, usuarioEligio) {
            const elegido = glyphElegidoUsuario(glyph);
            if (usuarioEligio && elegido) return elegido;
            return sanitizarGlifoPersistido({ nombre, glyph }) || elegido || '';
        }

        function glifoCatalogoPorNombre(nombre) {
            return HABIT_ICON_BY_NAME[claveIconoHabito(nombre)] || '';
        }

        function sanitizarGlifoPersistido(h) {
            const custom = String((h && h.glyph) || '').trim();
            if (!custom || !PH_ICON_PATHS[custom]) return '';
            if (custom === 'sparkle') return '';
            const mapped = glifoCatalogoPorNombre(h.nombre);
            if (mapped && custom === mapped) return '';
            return custom;
        }

        function claveGlifoHabito(nombre, glyphOverride) {
            const custom = String(glyphOverride || '').trim();
            const mapped = glifoCatalogoPorNombre(nombre);
            if (custom && PH_ICON_PATHS[custom] && custom !== 'sparkle') return custom;
            return mapped || 'sparkle';
        }

        function colorAcentoHabito(h) {
            const c = String((h && h.bgColor) || '').trim();
            if (!c || /^#10151f$/i.test(c)) return '';
            return c;
        }

        function htmlGlifoHabito(nombre, size, glyphOverride, color) {
            const key = claveGlifoHabito(nombre, glyphOverride);
            const s = size || 20;
            const fill = color || colorIconoHabito(nombre);
            return `<span class="habit-glyph" style="width:${s}px;height:${s}px">${svgPhosphorPorClave(key, s, fill)}</span>`;
        }

        function htmlTituloHabito(nombre, glyphOverride, color) {
            return `${htmlGlifoHabito(nombre, 20, glyphOverride, color)}<span class="habit-title-text">${escapeHtmlChat(cleanHabitName(nombre))}</span>`;
        }

        function hidratarGlifosPhosphor(root) {
            (root || document).querySelectorAll('[data-ph]').forEach(el => {
                const key = el.getAttribute('data-ph');
                el.classList.add('habit-glyph');
                el.innerHTML = svgPhosphorPorClave(key, 20, PH_ICON_COLOR[key] || PH_ICON_DEFAULT);
            });
        }

